import type { ReactNode } from 'react';

export interface SolarIconProps {
  size?: number;
  color?: string;
  style?: React.CSSProperties;
  className?: string;
}

const icon =
  (children: ReactNode) =>
  ({ size = 16, color = 'currentColor', style = {}, className, ...rest }: SolarIconProps) => (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      className={className}
      style={{ color, display: 'inline-block', ...style }}
      {...rest}
    >
      {children}
    </svg>
  );

