'use client';

/**
 * 弧面玻璃底栏 —— 移植自真题站（cet-site）的 bottom-nav：
 * 视觉复刻 GitHub: rit3zh/expo-curved-bottom-tabs（RN 组件），Web 端用同样的
 * 几何算法（computeCurvedArc / 透镜路径）重绘：玻璃药丸浮在向下凸起的弧面上，
 * 图标随弧面切线倾斜，药丸可拖拽并吸附到最近的 tab。
 *
 * 与真题站的差异：
 *  - 图标换成 Readest 语义（书架 / 继续阅读 / 添加书籍 / 设置 / 我的）
 *  - 玻璃色跟随 daisyUI 主题变量（--color-base-100 / --color-base-content），
 *    暗色模式自动适配，不写死深浅色
 */
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { ReactElement } from 'react';
import { SolarBook, SolarHome, SolarNotebook, SolarSettings, SolarUser } from '@/components/solar-icons';
import { useAppRouter } from '@/hooks/useAppRouter';
import { useLibraryStore } from '@/store/libraryStore';
import { useTranslation } from '@/hooks/useTranslation';
import { eventDispatcher } from '@/utils/event';
import { navigateToLibrary, navigateToProfile, navigateToReader } from '@/utils/nav';

// —— 与 expo-curved-bottom-tabs 的几何常量保持一致 ——
const ARC_HEIGHT = 16; // 弧面中部向上凸起的高度
const THICKNESS = 64; // 弧面条带厚度（即导航栏视觉高度）
const EDGE_PAD = 12; // 首个/末个 tab 中心到栏边的内边距
const PILL_HEIGHT = 50; // 玻璃药丸高度
const ICON_SIZE = 23; // 图标字号
const ICON_BOX = 44; // 图标命中/布局框

type IconType = (props: { size?: number; color?: string; className?: string }) => ReactElement;

const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), hi);

interface Arc {
  center: { x: number; y: number };
  radius: number;
  startAngle: number;
  endAngle: number;
}

/** 照搬 expo: compute-curved-arc.ts */
function computeCurvedArc(width: number, height: number): Arc {
  const x = width / 2;
  const y = Math.max(height, 0.0001);
  const w = Math.sqrt(x * x + y * y);
  const phi = Math.atan2(x, y);
  const radius = w / 2 / Math.cos(phi);
  const center = { x, y: radius };
  const theta = 2 * (Math.PI / 2 - phi);
  const startAngle = (3 * Math.PI) / 2 - theta;
  const endAngle = (3 * Math.PI) / 2 + theta;
  return { center, radius, startAngle, endAngle };
}

/** 照搬 expo: stroke-arc-path.ts（dx/dy 把弧面平移到栏坐标系） */
function lensPath(arc: Arc, thickness: number, dx: number, dy: number): string {
  const h = thickness / 2;
  const { center, radius, startAngle, endAngle } = arc;
  const pt = (r: number, a: number) => ({
    x: center.x + r * Math.cos(a) + dx,
    y: center.y + r * Math.sin(a) + dy,
  });
  const oS = pt(radius + h, startAngle);
  const oE = pt(radius + h, endAngle);
  const iS = pt(radius - h, startAngle);
  const iE = pt(radius - h, endAngle);
  return [
    `M ${oS.x.toFixed(2)} ${oS.y.toFixed(2)}`,
    `A ${radius + h} ${radius + h} 0 0 1 ${oE.x.toFixed(2)} ${oE.y.toFixed(2)}`,
    `A ${h} ${h} 0 0 1 ${iE.x.toFixed(2)} ${iE.y.toFixed(2)}`,
    `A ${radius - h} ${radius - h} 0 0 0 ${iS.x.toFixed(2)} ${iS.y.toFixed(2)}`,
    `A ${h} ${h} 0 0 1 ${oS.x.toFixed(2)} ${oS.y.toFixed(2)}`,
    'Z',
  ].join(' ');
}

const CurvedBottomNav = () => {
  const _ = useTranslation();
  const router = useAppRouter();
  const library = useLibraryStore((state) => state.library);

  const [width, setWidth] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [pillCenter, setPillCenter] = useState(0);
  const [activeIndex, setActiveIndex] = useState(0);
  const barRef = useRef<HTMLDivElement | null>(null);
  const dragRef = useRef<{ startX: number; startCenter: number } | null>(null);

  // 最近在读的一本：有进度且更新时间最新的书
  const recentBook = useMemo(() => {
    const candidates = library.filter(
      (book) => !book.deletedAt && book.progress && book.progress[0] > 0
    );
    return candidates.sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0))[0];
  }, [library]);

  const TABS = useMemo(
    () => [
      {
        key: 'library',
        label: _('Library'),
        Icon: SolarHome,
        onSelect: () => {
          setActiveIndex(0);
          navigateToLibrary(router);
        },
      },
      {
        key: 'reading',
        label: _('Continue Reading'),
        Icon: SolarBook,
        onSelect: () => {
          setActiveIndex(1);
          if (recentBook) {
            navigateToReader(router, [recentBook.hash]);
          } else {
            eventDispatcher.dispatch('toast', {
              message: _('No book in progress'),
              type: 'info',
            });
          }
        },
      },
      {
        key: 'add',
        label: _('Add Books'),
        Icon: SolarNotebook,
        onSelect: () => {
          setActiveIndex(2);
          eventDispatcher.dispatch('import-book-files');
        },
      },
      {
        key: 'settings',
        label: _('Settings'),
        Icon: SolarSettings,
        onSelect: () => {
          setActiveIndex(3);
          // 复用头栏的设置下拉（LibraryHeader 给它加了 .rd-settings-dropdown 标记）
          const toggle = document.querySelector<HTMLButtonElement>(
            '.rd-settings-dropdown button.dropdown-toggle'
          );
          toggle?.click();
        },
      },
      {
        key: 'profile',
        label: _('Profile'),
        Icon: SolarUser,
        onSelect: () => {
          setActiveIndex(4);
          navigateToProfile(router);
        },
      },
    ],
    [_, library, recentBook, router]
  );

  const count = TABS.length;

  const geom = useMemo(() => {
    if (width <= 0) return null;
    const innerWidth = Math.max(width - THICKNESS, 1);
    const arc = computeCurvedArc(innerWidth, ARC_HEIGHT);
    const radius = arc.radius;
    const centerX = width / 2;
    const centerY = radius + THICKNESS / 2;
    const halfSpan = innerWidth / 2;
    const barHeight = ARC_HEIGHT + THICKNESS;
    const slotWidth = (width - EDGE_PAD * 2) / count;
    const tabCenters = Array.from(
      { length: count },
      (_, i) => EDGE_PAD + slotWidth * (i + 0.5)
    );
    const pillWidth = Math.min(slotWidth * 1.12, 84);
    const path = lensPath(arc, THICKNESS, THICKNESS / 2, THICKNESS / 2);
    const centerlineY = (x: number) => {
      const dx = clamp(x - centerX, -halfSpan, halfSpan);
      return centerY - Math.sqrt(Math.max(radius * radius - dx * dx, 0));
    };
    return {
      radius,
      centerX,
      centerY,
      halfSpan,
      barHeight,
      slotWidth,
      tabCenters,
      pillWidth,
      path,
      centerlineY,
    };
  }, [width, count]);

  useLayoutEffect(() => {
    const el = barRef.current;
    if (!el) return;
    const measure = () => setWidth(el.clientWidth);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // 非拖拽时药丸吸附到当前激活 tab
  useEffect(() => {
    if (!geom) return;
    if (!dragging) setPillCenter(geom.tabCenters[clamp(activeIndex, 0, count - 1)]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [geom, activeIndex, dragging, count]);

  const onPointerDown = (e: React.PointerEvent) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    dragRef.current = { startX: e.clientX, startCenter: pillCenter };
    setDragging(true);
  };

  const onPointerMove = (e: React.PointerEvent) => {
    if (!dragging || !dragRef.current || !geom) return;
    const dx = e.clientX - dragRef.current.startX;
    const c = clamp(
      dragRef.current.startCenter + dx,
      geom.tabCenters[0],
      geom.tabCenters[count - 1]
    );
    setPillCenter(c);
  };

  const onPointerUp = (e: React.PointerEvent) => {
    if (!dragging || !dragRef.current || !geom) return;
    setDragging(false);
    const moved = Math.abs(e.clientX - dragRef.current.startX);
    let idx: number;
    if (moved < 6) {
      // 轻点：按落点所在 tab 区域跳转
      const rect = barRef.current!.getBoundingClientRect();
      const localX = e.clientX - rect.left;
      idx = clamp(Math.round((localX - EDGE_PAD) / geom.slotWidth - 0.5), 0, count - 1);
    } else {
      // 拖拽：吸附到最近的 tab
      idx = clamp(
        Math.round((pillCenter - EDGE_PAD) / geom.slotWidth - 0.5),
        0,
        count - 1
      );
    }
    setActiveIndex(idx);
    setPillCenter(geom.tabCenters[idx]);
    TABS[idx]?.onSelect();
  };

  if (!geom) {
    return (
      <div className='rd-curved-nav'>
        <div className='rd-curved-wrap'>
          <div className='rd-curved-bar' ref={barRef} />
        </div>
      </div>
    );
  }

  const {
    radius,
    centerX,
    centerY,
    halfSpan,
    barHeight,
    slotWidth,
    tabCenters,
    pillWidth,
    path,
    centerlineY,
  } = geom;

  const pillDx = clamp(pillCenter - centerX, -halfSpan, halfSpan);
  const pillYBase = Math.sqrt(Math.max(radius * radius - pillDx * pillDx, 0));
  const pillTop = centerY - pillYBase - PILL_HEIGHT / 2;
  const pillTilt = Math.atan2(pillDx, pillYBase);
  const pillLeft = pillCenter - pillWidth / 2;

  return (
    <div className='rd-curved-nav'>
      <div className='rd-curved-wrap'>
        <div
          className='rd-curved-bar'
          ref={barRef}
          style={{ height: barHeight }}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onPointerCancel={onPointerUp}
        >
          <div
            className='rd-curved-surface'
            style={{ clipPath: `path("${path}")`, WebkitClipPath: `path("${path}")` }}
          />
          {TABS.map((t, i) => {
            const x = tabCenters[i];
            const dx = clamp(x - centerX, -halfSpan, halfSpan);
            const yC = centerlineY(x);
            const tilt = Math.atan2(
              dx,
              Math.sqrt(Math.max(radius * radius - dx * dx, 0))
            );
            const d = Math.abs(pillCenter - x);
            const activeOp = clamp(1 - d / (slotWidth * 0.55), 0, 1);
            const idleOp = 1 - activeOp;
            const Icon = t.Icon;
            return (
              <div
                key={t.key}
                className='rd-curved-icon'
                title={t.label}
                aria-label={t.label}
                role='button'
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    t.onSelect();
                    setPillCenter(tabCenters[i]);
                  }
                }}
                style={{
                  left: x - ICON_BOX / 2,
                  top: yC - ICON_BOX / 2,
                  transform: `rotate(${tilt}rad)`,
                }}
              >
                <span className='glyph idle' style={{ opacity: idleOp }}>
                  <Icon size={ICON_SIZE} />
                </span>
                <span className='glyph active' style={{ opacity: activeOp }}>
                  <Icon size={ICON_SIZE} />
                </span>
              </div>
            );
          })}
          <div
            className={`rd-curved-pill${dragging ? ' dragging' : ''}`}
            style={{
              left: pillLeft,
              top: pillTop,
              width: pillWidth,
              transform: `rotate(${pillTilt}rad)`,
            }}
          />
        </div>
      </div>
    </div>
  );
};

export default CurvedBottomNav;
